    Bug 1995479 - Try to fix intermittent comm/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js. r=aleca


    As the comment above there says, the subfolder operations may not be finished.
    https://searchfox.org/comm-central/rev/bd0a4e007c0b355eef8397e542b5b4c046b743ee/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js#234-235

    Now succeeds with --verify, but didn't before.

    Differential Revision: https://phabricator.services.mozilla.com/D282031

diff --git a/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js b/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js
index 7f774eaa093..e481b8d3052 100644
--- a/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js
+++ b/mailnews/base/test/unit/test_moveCopyFoldersAcrossServers.js
@@ -11,6 +11,9 @@ const { PromiseTestUtils } = ChromeUtils.importESModule(
 const { ServerTestUtils } = ChromeUtils.importESModule(
   "resource://testing-common/mailnews/ServerTestUtils.sys.mjs"
 );
+const { TestUtils } = ChromeUtils.importESModule(
+  "resource://testing-common/TestUtils.sys.mjs"
+);

 const generator = new MessageGenerator();
 let imapSrcServer, imapDestServer;
@@ -207,9 +210,8 @@ async function subtestMove(folder, newParent) {
     destSubfolder,
     "the moved subfolder should have been created on the destination server"
   );
-  Assert.equal(
-    destSubfolder.getTotalMessages(false),
-    3,
+  await TestUtils.waitForCondition(
+    () => destSubfolder.getTotalMessages(false) == 3,
     "the moved subfolder should still contain the messages"
   );
   checkMessagesOnServer(destSubfolder, 3);
@@ -274,10 +276,10 @@ async function subtestCopy(folder, newParent) {
     destSubfolder,
     "the copied subfolder should have been created on the destination server"
   );
-  Assert.equal(
-    destSubfolder?.getTotalMessages(false),
-    2,
+  await TestUtils.waitForCondition(
+    () => destSubfolder.getTotalMessages(false) == 2,
     "the copied subfolder should contain a copy of the subfolder's messages"
   );
+
   checkMessagesOnServer(destSubfolder, 2);
 }
